#!/usr/bin/env node
// 產生長青 Topic 的國別文化筆記。
//
// dated observance 用 topic_observances；沒有固定日期的生活議題則用這份資料。
// 兩者不能混用：regional note 不會被當成節日、也不會進入日期排序。
// 文字是編輯資料，不是由頁面在 build 時拼湊出來；每筆都保留來源 URL，
// 讓 Topic 的 GEO/AEO 答案可以回到可查證的公共資料入口。
import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const OUT = join(ROOT, 'content', 'topic-regional-notes.json');
const LOCALES = ['zh-TW', 'en', 'ja', 'zh-CN', 'hi', 'id', 'pt-BR'];
const COUNTRIES = ['TW', 'JP', 'CN', 'US', 'IN', 'ID', 'BR'];

